# Let's verify it's bipartite
def is_bipartite(adj, n):
    color = {}
    for start in range(n):
        if start in color:
            continue
        color[start] = 0
        queue = [start]
        while queue:
            u = queue.pop(0)
            for v in adj[u]:
                if v not in color:
                    color[v] = 1 - color[u]
                    queue.append(v)
                elif color[v] == color[u]:
                    return False
    return True

print(f"Is bipartite: {is_bipartite(adj, 14)}")

# Find shortest cycle (girth)
from collections import deque
def find_girth(adj, n):
    min_cycle = float('inf')
    for start in range(n):
        # BFS from start
        dist = {start: 0}
        parent = {start: None}
        queue = deque([start])
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if v not in dist:
                    dist[v] = dist[u] + 1
                    parent[v] = u
                    queue.append(v)
                elif v != parent[u]:
                    # Found a cycle
                    cycle_len = dist[u] + dist[v] + 1
                    min_cycle = min(min_cycle, cycle_len)
    return min_cycle if min_cycle != float('inf') else None

girth = find_girth(adj, 14)
print(f"Girth: {girth}")

